(async () => {
  const r = await fetch('https://threeui.com/landing-pages/kage.html');
  if (!r.ok) throw new Error('HTTP ' + r.status);
  const html = await r.text();
  await Bun.write('D:/REACT/test/_ref/kage-source.html', html);

  const styleStart = html.indexOf('<style>');
  const styleEnd = html.indexOf('</style>');
  const bodyStart = html.indexOf('<body');
  const scripts = [...html.matchAll(/<script([^>]*)>/g)].map(m => ({ attrs: m[1].trim(), at: m.index }));
  console.log('total bytes:', html.length);
  console.log('style:', styleStart, '-', styleEnd, `(${styleEnd - styleStart} bytes)`);
  console.log('body starts at:', bodyStart);
  console.log('scripts:', JSON.stringify(scripts));
  const ids = [...html.matchAll(/<(section|header|footer|nav|main|div)\s[^>]*id="([\w-]+)"/g)].map(m => `${m[1]}#${m[2]}`);
  console.log('elemen ber-id:', JSON.stringify(ids));
  const assets = [...new Set([...html.matchAll(/(?:url\(|href=|src=)['"]?(secret-pathways-assets\/[^'")\s]+)/g)].map(m => m[1]))];
  console.log('assets:', JSON.stringify(assets, null, 1));
})();

