(async () => {
  const html = await Bun.file('D:/REACT/test/_ref/kage-source.html').text();
  const base = 'https://threeui.com/landing-pages/';
  const assets = [...new Set([...html.matchAll(/(?:url\(|href=|src=)['"]?(secret-pathways-assets\/[^'")\s]+)/g)].map(m => m[1]))];

  // unduh paralel
  const results = await Promise.all(assets.map(async rel => {
    const r = await fetch(base + rel);
    const dest = 'D:/REACT/test/_ref/' + rel;
    await Bun.write(dest, new Uint8Array(await r.arrayBuffer()));
    return `${rel}: ${r.status} (${(await Bun.file(dest).size)} B)`;
  }));
  console.log(results.join('\n'));

  // pisahkan potongan file
  const style = html.slice(html.indexOf('<style>') + 7, html.indexOf('</style>'));
  const bodyOpen = html.indexOf('<body');
  const bodyClose = html.lastIndexOf('</body>');
  const body = html.slice(html.indexOf('>', bodyOpen) + 1, bodyClose);
  const scriptStart = html.lastIndexOf('<script>');
  const scriptEnd = html.lastIndexOf('</script>');
  const appJs = html.slice(scriptStart + 8, scriptEnd);
  await Bun.write('D:/REACT/test/_ref/kage-style.css', style);
  await Bun.write('D:/REACT/test/_ref/kage-body.html', body);
  await Bun.write('D:/REACT/test/_ref/kage-app.js', appJs);
  console.log('\nCSS:', style.length, '| BODY:', body.length, '| APP JS:', appJs.length);

  // struktur top-level script inline (baris yang mulai blok/fungsi besar)
  const lines = appJs.split('\n');
  console.log('app.js total baris:', lines.length);
  const heads = [];
  lines.forEach((l, i) => {
    const m = l.match(/^(\s*)(?:const|let|var|function|async function)\s+([A-Za-z_$][\w$]*)/);
    if (m && m[1].length <= 2) heads.push(`${i + 1}: ${l.trim().slice(0, 80)}`);
  });
  console.log(heads.slice(0, 60).join('\n'));
})();

