(async () => {
  const appJs = await Bun.file('D:/REACT/test/_ref/kage-app.js').text();
  const lines = appJs.split('\n');

  // bagaimana script mulai jalan? cari init/boot/DOMContentLoaded
  const initLines = [];
  lines.forEach((l, i) => { if (/DOMContentLoaded|DOMContentLoaded|window\.onload|boot\(|init\(|requestAnimationFrame\s*\(\s*tick|\bTHREE\b/.test(l)) initLines.push(`${i+1}: ${l.trim().slice(0,90)}`); });
  console.log('== referensi init/THREE (pertama 25) ==');
  console.log(initLines.slice(0, 25).join('\n'));

  console.log('\n== 30 baris terakhir app.js ==');
  console.log(lines.slice(-30).map((l,i)=>`${lines.length-30+i+1}: ${l}`).join('\n'));

  const body = await Bun.file('D:/REACT/test/_ref/kage-body.html').text();
  const blines = body.split('\n');
  console.log('\n== body total baris:', blines.length, '==');
  // peta tag pembuka level atas
  blines.forEach((l, i) => {
    if (/^\s*<(section|header|footer|div id|nav|main)/i.test(l)) {
      console.log(`${i+1}: ${l.trim().slice(0, 100)}`);
    }
  });
})();

