(async () => {
  const R = 'D:/REACT/test';
  const cp = await import('node:child_process').then(m => m.execSync ? m : null);
  const fs = await import('node:fs');
  const path = await import('node:path');

  // ---------- 1. salin asset ke public/ ----------
  const copy = (srcRel, destRel) => {
    const s = R + '/' + srcRel, d = R + '/' + destRel;
    fs.mkdirSync(path.dirname(d), { recursive: true });
    fs.copyFileSync(s, d);
  };
  const gen = ['kage-sanmon-preview', 'kage-approach', 'kage-lantern-court', 'kage-moonwater'];
  gen.forEach(n => copy(`_ref/secret-pathways-assets/generated/${n}.webp`, `public/assets/generated/${n}.webp`));
  const fg = await Array.fromAsync(new Bun.Glob('*.webp').scan({ cwd: `${R}/_ref/secret-pathways-assets/foreground/png` }));
  fg.forEach(n => copy(`_ref/secret-pathways-assets/foreground/png/${n}`, `public/assets/foreground/png/${n}`));
  copy('_ref/secret-pathways-assets/three.min.js', 'public/assets/three.min.js');
  console.log('assets tersalin:', gen.length, '+', fg.length, '+ three.min.js');

  // ---------- 2. CSS dengan path diubah ----------
  let css = await Bun.file(`${R}/_ref/kage-style.css`).text();
  css = css.split('secret-pathways-assets/generated/').join('/assets/generated/')
           .split('secret-pathways-assets/foreground/png/').join('/assets/foreground/png/');
  fs.mkdirSync(`${R}/src/kage`, { recursive: true });
  await Bun.write(`${R}/src/kage/kage.css`, css);
  await Bun.write(`${R}/public/assets/fonts.css`, await Bun.file(`${R}/_ref/secret-pathways-assets/fonts.css`).text());
  console.log('kage.css:', css.length, '| fonts.css ke public');

  // ---------- 3. konverter HTML -> JSX ----------
  const ATTR_MAP = {
    'stroke-width': 'strokeWidth', 'stroke-linecap': 'strokeLinecap', 'stroke-linejoin': 'strokeLinejoin',
    'fill-opacity': 'fillOpacity', 'stroke-opacity': 'strokeOpacity', 'clip-path': 'clipPath',
    'fill-rule': 'fillRule', 'clip-rule': 'clipRule', 'stop-color': 'stopColor', 'stop-opacity': 'stopOpacity',
    'font-size': 'fontSize', 'font-family': 'fontFamily', 'text-anchor': 'textAnchor',
    'stroke-dasharray': 'strokeDasharray', 'stroke-miterlimit': 'strokeMiterlimit',
  };
  const VOID = new Set(['br', 'hr', 'img', 'input', 'source', 'meta', 'link']);
  function htmlToJsx(t) {
    t = t.replace(/<!--[\s\S]*?-->/g, '');                       // komentar html dibuang
    t = t.replace(/\bclass=/g, 'className=');
    t = t.replace(/\s([a-z]+(?:-[a-z]+)+)=(?=")/g, (m, a) =>
      a.startsWith('data-') || a.startsWith('aria-') ? ` ${a}=` : ` ${ATTR_MAP[a] || a}=`);
    // inline style -> object
    t = t.replace(/style="([^"]*)"/g, (m, s) => {
      const obj = s.split(';').filter(Boolean).map(p => {
        let [k, v] = p.split(':').map(x => x.trim());
        k = k.startsWith('--') ? `'${k}'` : k.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
        v = /^[\d.]+$/.test(v) ? v : `'${v.replace(/'/g, "\\'")}'`;
        return `${k}: ${v}`;
      }).join(', ');
      return `style={{ ${obj} }}`;
    });
    // void elements -> self-closing
    t = t.replace(/<(img|br|hr|input|source)((?:[^>"']|"[^"]*"|'[^']*')*?)\s*\/?>/g, '<$1$2 />');
    return t;
  }

  // ---------- 4. potong body jadi komponen ----------
  const body = await Bun.file(`${R}/_ref/kage-body.html`).text();
  const blines = body.split('\n');
  const findLine = (re) => blines.findIndex(l => re.test(l)) + 1; // 1-based
  const marks = {
    vignette: findLine(/id="vignette"/),
    grain: findLine(/id="grain"/),
    pre: findLine(/id="pre"/),
    nav: findLine(/header class="nav"/),
    hero: findLine(/section class="hero"/),
    gate: findLine(/section class="sec" id="gate"/),
    pathways: findLine(/id="pathways"/),
    lessons: findLine(/id="lessons"/),
    eternity: findLine(/id="eternity"/),
    footer: findLine(/footer class="foot"/),
    fgsky: findLine(/id="fg-sky"/),
  };
  console.log('batas section:', JSON.stringify(marks));
  const slice = (a, b) => blines.slice(a - 1, b).join('\n').trim();

  // cari akhir tiap blok: baris penutup tag pembuka level atas
  const closeOf = (startTagRe) => {
    const i = blines.findIndex(l => startTagRe.test(l));
    const indent = blines[i].match(/^\s*/)[0];
    const closing = indent + '</' + blines[i].trim().slice(1).split(/[\s>]/)[0] + '>';
    for (let j = i + 1; j < blines.length; j++) if (blines[j].startsWith(closing)) return j + 1;
    throw new Error('closing not found for ' + closing);
  };
  const bounds = {};
  bounds.pre = closeOf(/<div id="pre">/);
  bounds.nav = closeOf(/<header class="nav" id="nav">/);
  bounds.hero = closeOf(/<section class="hero" id="hero"/);
  bounds.gate = closeOf(/<section class="sec" id="gate"/);
  bounds.pathways = closeOf(/<section class="sec" id="pathways"/);
  bounds.lessons = closeOf(/<section class="sec" id="lessons"/);
  bounds.eternity = closeOf(/<section class="sec fin" id="eternity"/);
  bounds.footer = closeOf(/<footer class="foot"/);

  const comps = {
    Preloader: slice(marks.pre, bounds.pre),
    Nav: slice(marks.nav, bounds.nav),
    Hero: slice(marks.hero, bounds.hero),
    Gate: slice(marks.gate, bounds.gate),
    Pathways: slice(marks.pathways, bounds.pathways),
    Lessons: slice(marks.lessons, bounds.lessons),
    Eternity: slice(marks.eternity, bounds.eternity),
    Footer: slice(marks.footer, bounds.footer),
  };
  for (const [name, raw] of Object.entries(comps)) {
    const jsx = htmlToJsx(raw);
    const out = `// ${name} — ported dari Kage landing page (threeui.com).\n// Edit bebas: markup ini adalah tampilan; logika scroll/Three.js ada di src/kage/world.js\nexport default function ${name}() {\n  return (\n    <>\n${jsx.split('\n').map(l => '      ' + l).join('\n')}\n    </>\n  );\n}\n`;
    await Bun.write(`${R}/src/components/${name}.jsx`, out);
  }
  console.log('komponen ditulis:', Object.keys(comps).join(', '), '| ukuran:', Object.values(comps).map(c => c.length).join('/'));

  // overlay (vignette+grain) & sisanya (fg-sky, rail, cursor...) — simpan sisa tail untuk App
  const tailStart = marks.fgsky;
  const tail = blines.slice(tailStart - 1).join('\n').trim();
  await Bun.write(`${R}/_ref/kage-tail.html`, tail);
  console.log('tail (fg-sky dst):', tail.length, 'chars,', tail.split('\n').length, 'baris');
})();

