(async () => {
  const { chromium } = await import('playwright');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text().slice(0, 200)); });

  await page.goto('http://localhost:5173/', { waitUntil: 'load' });

  // tunggu boot dunia Three.js (window.__kage dipasang di akhir boot())
  let booted = false;
  try {
    await page.waitForFunction('!!window.__kage', null, { timeout: 25000 });
    booted = true;
  } catch {}

  const state = await page.evaluate(() => ({
    booted: !!window.__kage,
    rootChildren: document.getElementById('root')?.children.length ?? 0,
    hasCanvasGL: !!document.getElementById('gl'),
    heroExists: !!document.getElementById('hero'),
    navExists: !!document.getElementById('nav'),
    preDone: document.getElementById('pre')?.classList.contains('done'),
    sections: ['gate','pathways','lessons','eternity'].map(id => !!document.getElementById(id)),
    canvasSize: (() => { const c = document.getElementById('gl'); return c ? c.width + 'x' + c.height : 'none'; })(),
    bodyLockedRemoved: !document.body.classList.contains('is-locked'),
  }));
  console.log(JSON.stringify(state, null, 1));
  console.log('errors:', errors.length ? errors.slice(0, 10).join('\n') : '(tidak ada)');

  await page.screenshot({ path: 'D:/REACT/test/_ref/smoke-hero.png' });
  await browser.close();
})();

