(async () => {
  const fs = await import('node:fs');
  const candidates = [
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
  ];
  const exe = candidates.find(p => fs.existsSync(p));
  if (!exe) { console.log('tidak ada browser sistem'); return; }
  console.log('browser:', exe);

  const { default: puppeteer } = await import('puppeteer-core');
  const browser = await puppeteer.launch({ executablePath: exe, headless: 'new', args: ['--no-sandbox', '--use-angle=swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message.slice(0, 300)));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text().slice(0, 200)); });

  await page.goto('http://localhost:5173/', { waitUntil: 'load', timeout: 60000 });

  let booted = false;
  try {
    await page.waitForFunction('!!window.__kage', { timeout: 30000 });
    booted = true;
  } catch {}
  await new Promise(r => setTimeout(r, 2500)); // beri waktu intro & preloader

  const state = await page.evaluate(() => ({
    booted: !!window.__kage,
    rootChildren: document.getElementById('root')?.children.length ?? 0,
    heroExists: !!document.getElementById('hero'),
    sections: ['gate','pathways','lessons','eternity'].map(id => !!document.getElementById(id)),
    preDone: !!document.getElementById('pre')?.classList.contains('done'),
    canvasSize: (() => { const c = document.getElementById('gl'); return c ? c.width + 'x' + c.height : 'none'; })(),
    bodyUnlocked: !document.body.classList.contains('is-locked'),
  }));
  console.log(JSON.stringify(state, null, 1));
  console.log('errors:', errors.length ? '\n' + errors.slice(0, 12).join('\n') : '(tidak ada)');

  await page.screenshot({ path: 'D:/REACT/test/_ref/smoke-hero.png' });
  await browser.close();
  console.log('screenshot: _ref/smoke-hero.png');
})();

