(async () => {
  const { default: puppeteer } = await import('puppeteer-core');
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    headless: 'new', args: ['--no-sandbox', '--use-angle=swiftshader'],
  });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message.slice(0, 200)));
  await page.goto('http://localhost:5173/', { waitUntil: 'networkidle0', timeout: 60000 });
  await page.waitForFunction('!!window.__kage', { timeout: 30000 });
  await new Promise(r => setTimeout(r, 1200));

  await page.evaluate(() => scrollTo(0, window.__kage.anchors()[2]));
  await new Promise(r => setTimeout(r, 3500));

  const st = await page.evaluate(() => {
    const imgs = [...document.querySelectorAll('img')];
    return {
      totalImg: imgs.length,
      loaded: imgs.filter(i => i.complete && i.naturalWidth > 0).length,
      broken: imgs.filter(i => i.complete && i.naturalWidth === 0).map(i => i.src),
      activeChip: document.querySelector('.chip.on b')?.textContent ?? null,
    };
  });
  console.log(JSON.stringify(st, null, 1));
  console.log('errors:', errors.length ? errors.join('\n') : '(tidak ada)');
  await page.screenshot({ path: 'D:/REACT/test/_ref/smoke-pathways-2.png' });
  await browser.close();
})();
